static double conv_speed(double kmh)
{
    return s_unit_mile ? kmh / KM_PER_MILE : kmh;
}

static const char *unit_dist(void) { return s_unit_mile ? "mile" : "km"; }
static const char *unit_speed(void) { return s_unit_mile ? "mph" : "km/h"; }

/** 当前时间（含时区与 12/24 小时制）；minutes 是本地 UTC+8 的分钟数。 */
static void fmt_clock(int minutes, char *buf, size_t n)
{
    int m = (minutes + (s_tz - 8) * 60) % (24 * 60);

    if (m < 0) m += 24 * 60;
    if (s_h24) {
        snprintf(buf, n, "%d:%02d", m / 60, m % 60);
    } else {
        int h = m / 60;
        const char *ap = (h >= 12) ? "PM" : "AM";

        h %= 12;
        if (h == 0) h = 12;
        snprintf(buf, n, "%d:%02d %s", h, m % 60, ap);
    }
}

/** 坡度：% ↔ °（同一个几何坡度两种表述）。 */
static double grade_val(double pct)
{
    return s_grade_deg ? atan(pct / 100.0) * 180.0 / 3.141592653589793 : pct;
}

static const char *grade_unit(void) { return s_grade_deg ? "°" : "%"; }

/** 自动暂停：速度 < 2 km/h 连续 10 s 触发；>= 2.5 km/h 自动恢复。 */
#define AUTO_PAUSE_ENTER_KMH 2.0
#define AUTO_PAUSE_EXIT_KMH  2.5
#define AUTO_PAUSE_HOLD_S    10

static void ride_step(void)
{
    R.seed = R.seed * 1103515245u + 12345u;
    R.t += 1.0;
    {
        const double n = (double)((R.seed >> 16) & 0x7FFF) / 32767.0 - 0.5;
        double sp = 22.5 + 5.5 * sin(R.t / 8.0) + 1.6 * n;

        /* 演示语义：每 60 s 有一个 14 s 的“红灯/推车”段（速度 0），
         * 自动暂停在静止 10 s 后触发、放行后自动恢复。 */
        if (fmod(R.t, 60.0) >= 46.0) {
            sp = 0.0;
        }
        if (sp > 0.0 && sp < 8.0) sp = 8.0;
        if (sp > 45.0) sp = 45.0;
        R.target = sp;
        if (R.paused) {
            R.speed = 0.0;
            R.cadence = 0;
            R.power = 0;
            if (R.hr > 96) R.hr--;
            return;
        }
        R.speed = sp;
        R.dist_km += sp / 3600.0;
        R.hr = 126 + (int)(sp * 1.05) + (int)(3.0 * n);
        R.cadence = sp <= 0.0 ? 0 : 78 + (int)(sp * 0.5) + (int)(4.0 * n);
        R.power = sp <= 0.0 ? 0 : (int)(120.0 + sp * 2.6 + 10.0 * n);
        R.elevation = 326 + (int)(9.0 * sin(R.t / 21.0));
        if (n > 0.28) {
            R.ascent += 1;
        }
        R.cal = (int)(R.dist_km * 32.0);
        if (R.speed > R.max) {
            R.max = R.speed;
        }
        R.avg = (R.elapsed_s > 0)
                    ? R.dist_km / ((double)R.elapsed_s / 3600.0)
                    : R.speed;
    }
    {
        const double s = R.speed;
        const int bin = (s < 15.0) ? 0 : (s < 25.0) ? 1 : (s < 35.0) ? 2
                      : (s < 45.0) ? 3 : 4;

        R.hist[bin]++;
    }
}

/** 1 Hz 骑行推进（暂停时停表/停里程；自动暂停判定用未门控速度）。 */
static void ride_advance_1s(void)
{
    if (!R.active) {
        return;
    }
    if (!R.paused) {
        R.elapsed_s++;      /* 先记这一秒，ride_step() 的均速用同一分母 */
    }
    ride_step();
    if (!R.paused && R.target < AUTO_PAUSE_ENTER_KMH) {
        R.still_s++;
        if (R.still_s >= AUTO_PAUSE_HOLD_S) {
            R.paused = true;
            R.auto_paused = true;
            R.speed = 0.0;
            R.cadence = 0;
            R.power = 0;
            toast("自动暂停 · 速度低于 2 km/h");
        }
    } else if (!R.paused) {
        R.still_s = 0;
    }
    if (R.paused && R.auto_paused && R.target >= AUTO_PAUSE_EXIT_KMH) {
        R.paused = false;
        R.auto_paused = false;
        R.still_s = 0;
        toast("自动继续");
    }
}

